{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "International alliance and AGREE-ment of 71 clinical practice guidelines on the management of critical care patients with COVID-19: a living systematic review",
      "reason": "The title explicitly includes the phrase 'systematic review' (more specifically 'a living systematic review'), identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "International alliance and AGREE-ment of 71 clinical practice guidelines on the management of critical care patients with COVID-19: a living systematic review",
      "reason": "The title specifies the population and scope ('critical care patients with COVID-19') and the subject ('71 clinical practice guidelines' on their management), providing key information about the review question/objective."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "International alliance and AGREE-ment of 71 clinical practice guidelines on the management of critical care patients with COVID-19: a living systematic review",
      "reason": "The title indicates the review is a 'living systematic review' (update status) and specifies the included evidence type ('clinical practice guidelines') and the number included (71), providing relevant supplementary information."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "A possible explanation might be the extreme conditions under which these CPGs were developed including global uncertainty about the natural history of the COVID-19 infection, the lack of direct evidence, and external pressures to produce rapid advice, lack of technical capacity to develop high-quality CPGs, among others. Moreover, the continuously evolving evidence landscape of COVID-19 would require an ongoing process of monitoring and updating as some recommendations are likely to change [96].",
      "reason": "The manuscript describes the current state (evolving evidence, lack of direct evidence) and important uncertainties affecting guideline development."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Given the extraordinary burden that the pandemic has created on the emergency and critical care units worldwide, there is an urgent need for evidence-based guidance to facilitate optimal clinical and policy decisionmaking.",
      "reason": "The authors explain the importance and need for the review, citing the pandemic burden and the urgent requirement for evidence-based guidance for critical care."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Four previous reviews have assessed the quality of COVID-19 CPGs [16-18]. Two of them focused on the CPGs produced in the early phase of the pandemic. Zhao et al. evaluated CPGs for 5 different viruses, including SARS-CoV2, that have caused public health emergencies of international concern over 20 years, with search date ending February 2, 2020. Dagens et al. study focused on the early stage of the pandemic, with search date up to March 14, 2020 [1]. ... However, an assessment of all the CPGs focused on the management of critically ill COVID -19 patients was lacking. We, therefore, aimed to systematically identify the CPGs for the management of critically ill patients with COVID-19, and critically assess their quality for both clinical and methodological purposes.",
      "reason": "The manuscript cites prior reviews and explicitly states a gap (lack of comprehensive assessment for critically ill patients), justifying the need for the current review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is of clinical practice guidelines for critical care rather than a review of intervention effects; no proposed mechanism of action for specific interventions is described in the provided evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model or hypothesised relationships between intervention components and outcomes are presented; the manuscript focuses on appraisal of guidelines rather than evaluation of complex interventions."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_1",
      "quote": "Objective: We aimed to systematically identify and critically assess the clinical practice guidelines (CPGs) for the management of critically ill patients with COVID-19 with the AGREE II instrument.",
      "reason": "The review objective is explicitly stated (to identify and critically assess CPGs for critically ill COVID-19 patients using AGREE II), but it is not presented using a recognized question-formulation framework (e.g., PICO or similar)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_1",
      "quote": "Objective: We aimed to systematically identify and critically assess the clinical practice guidelines (CPGs) for the management of critically ill patients with COVID-19 with the AGREE II instrument.",
      "reason": "The review focuses on identifying and assessing clinical practice guidelines (CPGs) rather than evaluating intervention effects; therefore planned comparisons in PICO format for intervention effects are not applicable."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Selection criteria For inclusion, CPGs had to provide specific recommendations for clinical management, diagnosis and/or treatment of critically ill patients with COVID-19. When more than one version was available, we included only the most updated version or edition of the eligible RGs.",
      "reason": "The manuscript specifies the target population (critically ill patients with COVID-19) and the type of documents (CPGs providing specific recommendations) and a rule for multiple versions, but does not fully specify other study-eligibility characteristics requested by the checklist (e.g., eligible study designs beyond CPGs, settings, follow-up requirements, or full question-framework components)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_16",
      "quote": "We conducted a comprehensive search the most important databases, and we did not apply any language restrictions. ... the assessments were conducted only on CPGs that were either published in peer review journals or posted in official websites as CPG full documents, without considering unpublished or supplementary material, therefore, it is possible that some information was missing to inform the quality of the CPGs in this iteration but it is planned to be covered in the following series of this living review.",
      "reason": "The review states language policy (no language restrictions) and limits on publication/report status (only peer-reviewed or official website CPG full documents), but does not report any criteria about dissemination year or other report-characteristic restrictions, so reporting of report-characteristic eligibility is incomplete."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "Selection criteria For inclusion, CPGs had to provide specific recommendations for clinical management, diagnosis and/or treatment of critically ill patients with COVID-19.",
      "reason": "This review assesses clinical practice guidelines (CPGs) rather than primary studies measuring outcomes; the retrieved evidence contains no information on excluding reports because outcomes were not measured versus not reported, so the outcome-based distinction does not apply to this guideline-focused review."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "The table summarizes the scope of the recommendations. Each row shows the most common interventions of interest in critical patients with COVID-19 (general supportive care and therapeutic interventions). The second column displays the number of guidelines that cover each recommendation, and the following columns describes the guidelines that provide recommendations for each intervention of interest categorized as Low, Moderate or High quality according to AGREE score obtained in domain 3.",
      "reason": "The manuscript specifies how guidelines were grouped in the syntheses (rows by interventions; columns by number of guidelines and by quality categories: Low/Moderate/High linked to AGREE D3), which links synthesized groups to comparisons of interest."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "We had to exclude, for now, CPGs that were written in languages that were not covered by our research team (i.e., Japanese).",
      "reason": "The authors state a notable restriction (exclusion of CPGs in languages not covered by the team) and provide a rationale (language coverage limitations), satisfying the requirement to justify notable eligibility restrictions."
    }
  ],
  "confidence": 75
}

